import{_ as e,o as t,c as s,a5 as c}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"C# 内存诊断：GC 频繁、OOM 与内存泄漏","description":"本页回答三个问题：内存持续增长或 OOM 时如何定位，GC 频繁和真正的内存泄漏如何区分，如何用转储和快照找到占用者。机制见GC。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md","filePath":"csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"}'),i={name:"csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"};function r(o,a,d,m,n,l){return t(),s("div",null,[...a[0]||(a[0]=[c('<h1 id="c-内存诊断-gc-频繁、oom-与内存泄漏" tabindex="-1" data-src-line="2" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">C# 内存诊断：GC 频繁、OOM 与内存泄漏 <a class="header-anchor" href="#c-内存诊断-gc-频繁、oom-与内存泄漏" aria-label="Permalink to &quot;C# 内存诊断：GC 频繁、OOM 与内存泄漏&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">本页回答三个问题：内存持续增长或 OOM 时如何定位，GC 频繁和真正的内存泄漏如何区分，如何用转储和快照找到占用者。机制见<a href="./../../02-dotnet-runtime/chapter-03-gc.html">GC</a>。</p><h2 id="_1-先分清现象" tabindex="-1" data-src-line="6" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">1. 先分清现象 <a class="header-anchor" href="#_1-先分清现象" aria-label="Permalink to &quot;1. 先分清现象&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">内存问题有三种不同表象，根因和排查方式不同：</p><ul data-src-line="10" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><li data-src-line="10" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><strong>内存缓慢增长后 OOM</strong>：通常是泄漏——对象不再被业务使用，但仍被引用，GC 无法回收。</li><li data-src-line="11" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><strong>GC 频繁、CPU 高</strong>：分配速率过高，或堆太小，GC 忙于回收。</li><li data-src-line="12" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><strong>非托管内存增长</strong>：托管堆正常，但进程内存涨，通常是 P/Invoke 或原生资源泄漏。</li></ul><p data-src-line="14" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">先确认是哪种，再选择工具。用 <code>dotnet-counters</code> 看托管堆、分配速率和 GC 次数，区分「托管泄漏」和「非托管增长」。</p><h2 id="_2-采集证据" tabindex="-1" data-src-line="16" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">2. 采集证据 <a class="header-anchor" href="#_2-采集证据" aria-label="Permalink to &quot;2. 采集证据&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">用 <code>dotnet-counters</code> 观察实时指标：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet-counters monitor --process-id &lt;pid&gt; System.Runtime</span></span></code></pre></div><p data-src-line="24" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">关注 <code>gc-heap-size</code>（托管堆大小）、<code>alloc-rate</code>（分配速率）、<code>% Time in GC</code>。若 <code>gc-heap-size</code> 持续增长且不回落，是托管泄漏；若进程内存涨但 <code>gc-heap-size</code> 稳定，是非托管泄漏。</p><p data-src-line="26" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">用 <code>dotnet-gcdump</code> 采集托管堆快照：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet-gcdump collect --process-id &lt;pid&gt;</span></span></code></pre></div><p data-src-line="32" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">生成快照后，用 Visual Studio 或 <code>dotnet-dump</code> 分析，找出占用内存最大的对象和持有它们的引用链。</p><h2 id="_3-定位引用链" tabindex="-1" data-src-line="34" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">3. 定位引用链 <a class="header-anchor" href="#_3-定位引用链" aria-label="Permalink to &quot;3. 定位引用链&quot;">​</a></h2><p data-src-line="36" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">内存泄漏的根因是「对象被谁持有」。快照分析工具能给出「谁引用了这些对象」的引用链。常见泄漏来源：</p><ul data-src-line="38" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><li data-src-line="38" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">静态集合或缓存：往 <code>static List</code>/<code>Dictionary</code> 里加对象却从不移除。</li><li data-src-line="39" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">事件订阅：订阅了事件却没取消，发布者持有订阅者。</li><li data-src-line="40" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">未释放的非托管资源：<code>IDisposable</code> 没被 <code>using</code>（见<a href="./../../02-dotnet-runtime/chapter-05-unmanaged-interop.html">非托管互操作</a>）。</li><li data-src-line="41" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">长生命周期委托/闭包：Lambda 捕获了对象，存入长生命周期容器。</li></ul><p data-src-line="43" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">定位到引用链后，判断这条引用是否「本该断开却没断开」。GC 判断可达性是机械的，它无法区分「业务还需要」和「业务已不需要」。</p><h2 id="_4-区分泄漏与缓存" tabindex="-1" data-src-line="45" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">4. 区分泄漏与缓存 <a class="header-anchor" href="#_4-区分泄漏与缓存" aria-label="Permalink to &quot;4. 区分泄漏与缓存&quot;">​</a></h2><p data-src-line="47" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">不是所有内存增长都是泄漏。有界缓存（LRU、带上限）会增长到上限后稳定，这是预期行为。真正的泄漏是「无界增长」。观察内存是否随负载增加而持续单调增长、且负载停止后仍不回落，是判断泄漏的关键。</p><h2 id="_5-修复与验证" tabindex="-1" data-src-line="49" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">5. 修复与验证 <a class="header-anchor" href="#_5-修复与验证" aria-label="Permalink to &quot;5. 修复与验证&quot;">​</a></h2><p data-src-line="51" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">修复内存问题通常是对症：</p><ul data-src-line="53" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><li data-src-line="53" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">泄漏：断开不该存在的引用（移除静态集合条目、取消事件订阅、<code>Dispose</code> 非托管资源）。</li><li data-src-line="54" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">分配过高：减少分配（值类型、<code>Span&lt;T&gt;</code>、对象池，见<a href="./../../02-dotnet-runtime/chapter-02-type-layout-memory.html">类型布局与内存</a>）。</li></ul><p data-src-line="56" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">修复后重新采集快照和指标，确认 <code>gc-heap-size</code> 或进程内存不再持续增长。内存问题修复要量化验证，不能凭「看起来好多了」。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="58" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="60" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><li data-src-line="60" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><a href="./../../02-dotnet-runtime/chapter-03-gc.html">GC</a>解释分代回收与触发机制。</li><li data-src-line="61" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><a href="./../../02-dotnet-runtime/chapter-02-type-layout-memory.html">类型布局与内存</a>解释分配如何产生。</li><li data-src-line="62" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><a href="./../../02-dotnet-runtime/chapter-05-unmanaged-interop.html">非托管互操作</a>解释非托管资源泄漏。</li><li data-src-line="63" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><a href="./chapter-02-oom-case.html">缓存无界增长 OOM 案例</a>看一次完整的内存泄漏排查。</li></ul><blockquote data-src-line="65" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md"><p data-src-line="65" data-src-file="csharp/07-diagnostics/01-memory/chapter-01-memory-diagnostics.md">本页的技术边界按 .NET 10 / C# 14 核对；<code>dotnet-counters</code>、<code>dotnet-gcdump</code>、<code>dotnet-dump</code> 随 .NET SDK 提供。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/" target="_blank" rel="noreferrer">.NET 诊断</a>、<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/dotnet-gcdump" target="_blank" rel="noreferrer">分析内存使用</a>。</p></blockquote>',26)])])}const g=e(i,[["render",r]]);export{h as __pageData,g as default};
